mapper.select:
SELECT COUNT(*) FROM resource_slot
WHERE outlet_id = #{outletId} AND item_id = #{itemId} AND service_date = #{serviceDate}
  AND deleted = 0 AND start_time < #{endTime} AND end_time > #{startTime}
AND id != #{excludedId}

mapper.sql:
deleted = 0
AND outlet_id = #{outletId}
AND item_id = #{itemId}
AND service_date >= #{dateFrom}
AND service_date <= #{dateTo}
AND status = #{status}

mapper.select:
SELECT  FROM resource_slot s
JOIN service_outlet o ON o.id = s.outlet_id AND o.deleted = 0
JOIN service_item i ON i.id = s.item_id AND i.deleted = 0
WHERE s.deleted = 0 AND s.id > #{afterId}
  AND s.release_at >= #{releaseFrom} AND s.release_at < #{releaseTo}
  AND s.status IN ('SCHEDULED','SUSPENDED')
ORDER BY s.id LIMIT #{size}

SELECT  FROM resource_slot s
JOIN service_outlet o ON o.id = s.outlet_id AND o.deleted = 0
JOIN service_item i ON i.id = s.item_id AND i.deleted = 0
WHERE s.deleted = 0 AND s.id > #{afterId}
  AND s.release_at <= #{at}
  AND (s.service_date > #{today}
       OR (s.service_date = #{today} AND s.end_time > #{localTime}))
  AND s.status IN ('OPEN','SCHEDULED','SUSPENDED')
ORDER BY s.id LIMIT #{size}
